async function syncProjectResults(projectId){
 const rr=(await dbx.from('quarterly_reports').select('*').eq('project_id',projectId).order('annual_period').order('quarter')).data||[];
 const approved=rr.filter(r=>String(r.status||'').includes('معتمد')||r.status==='approved');
 const source=approved.length?approved:rr; const latest=source.length?source[source.length-1]:null;
 let totalSpend=0,totalLc=0,smeValue=0;
 source.forEach(r=>{const d=r.report_data||{},p=d.purchases||{},sv=d.services||{},sp=Number(d.omani_salary||0)+Number(d.foreign_salary||0)+Object.values(p).reduce((a,x)=>a+Number(x||0),0)+Object.values(sv).reduce((a,x)=>a+Number(x||0),0)+Number(d.subcontracts||0),lc=Number(d.total_local_content||0);if(String(d.report_type||'').includes('تراكمي')){totalSpend=sp;totalLc=lc}else{totalSpend+=sp;totalLc+=lc}smeValue+=Number(sv['خدمة مزود من المؤسسات الصغيرة و المتوسطة']||0)+Number(d.subcontracts||0)});
 const p=(projects||[]).find(x=>x.id===projectId);if(!p)return;const d=latest?.report_data||{},wf=Number(d.workforce_total||0),om=Number(d.omani_total||0),v=Number(p.total_project_value||0),oman=wf?om/wf*100:0;
 const w=d.workforce||[],g=n=>w.find(x=>Number(x.category_no)===n)||{};
 await dbx.from('projects').update({total_spend:totalSpend,total_local_content:totalLc,local_content_spend_pct:totalSpend?totalLc/totalSpend*100:0,local_content_project_pct:v?totalLc/v*100:0,sme_pct:v?smeValue/v*100:0,current_omani:om,non_omani:Math.max(0,wf-om),omanization_pct:oman,cat1_omani:Number(g(1).omani_count||0),cat1_non_omani:Number(g(1).foreign_count||0),cat2_omani:Number(g(2).omani_count||0),cat2_non_omani:Number(g(2).foreign_count||0),cat3_omani:Number(g(3).omani_count||0),cat3_non_omani:Number(g(3).foreign_count||0)}).eq('id',projectId);
}
